            if len(obj) >= 2 and isinstance(obj[0], (int, float)) and isinstance(obj[1], (int, float)):
                return (int(obj[0]), int(obj[1]))
        if isinstance(obj, dict):
            for kx, ky in (("x", "y"), ("col", "row"), ("cx", "cy")):
